-- Permanent exact-scope closure. This is never a physical-GC/withdrawal ACK.
CREATE TABLE nextcloud_onboarding_target_closures (
 operation_id TEXT PRIMARY KEY REFERENCES nextcloud_onboarding_operations(operation_id),
 closure_id TEXT NOT NULL UNIQUE CHECK(length(closure_id)=64),
 tenant_id BIGINT NOT NULL CHECK(tenant_id>0),knowledge_base_id TEXT NOT NULL,
 instance_id TEXT NOT NULL,binding_id TEXT NOT NULL,
 operation_revision BIGINT NOT NULL CHECK(operation_revision>0),
 reason TEXT NOT NULL CHECK(reason IN ('tenant_deleted','knowledge_base_deleted')),
 deletion_time_ms BIGINT NOT NULL CHECK(deletion_time_ms>0),
 closed_at_ms BIGINT NOT NULL CHECK(closed_at_ms>=deletion_time_ms),
 recovery_plan_sha256 TEXT NOT NULL DEFAULT '',
 UNIQUE(tenant_id,knowledge_base_id),UNIQUE(instance_id,binding_id));
CREATE TABLE nextcloud_onboarding_tenant_deletions (
 tenant_id BIGINT PRIMARY KEY CHECK(tenant_id>0),
 deletion_id TEXT NOT NULL UNIQUE CHECK(length(deletion_id)=64),
 deletion_time_ms BIGINT NOT NULL CHECK(deletion_time_ms>0),
 closed_at_ms BIGINT NOT NULL CHECK(closed_at_ms>=deletion_time_ms),
 recovery_plan_sha256 TEXT NOT NULL DEFAULT '');
CREATE TRIGGER nextcloud_target_closure_immutable_update BEFORE UPDATE ON nextcloud_onboarding_target_closures
WHEN 1 BEGIN SELECT RAISE(ABORT,'nextcloud_target_closed'); END;
CREATE TRIGGER nextcloud_target_closure_immutable_delete BEFORE DELETE ON nextcloud_onboarding_target_closures
WHEN 1 BEGIN SELECT RAISE(ABORT,'nextcloud_target_closed'); END;
CREATE TRIGGER nextcloud_tenant_deletion_immutable_update BEFORE UPDATE ON nextcloud_onboarding_tenant_deletions
WHEN 1 BEGIN SELECT RAISE(ABORT,'nextcloud_target_closed'); END;
CREATE TRIGGER nextcloud_tenant_deletion_immutable_delete BEFORE DELETE ON nextcloud_onboarding_tenant_deletions
WHEN 1 BEGIN SELECT RAISE(ABORT,'nextcloud_target_closed'); END;
CREATE TRIGGER nextcloud_tenant_deletion_insert_guard BEFORE INSERT ON nextcloud_onboarding_tenant_deletions
WHEN NOT ((NEW.recovery_plan_sha256='' AND EXISTS(SELECT 1 FROM tenants t WHERE t.id=NEW.tenant_id AND t.deleted_at IS NOT NULL)) OR (NEW.recovery_plan_sha256<>'' AND EXISTS(SELECT 1 FROM nextcloud_publication_recovery_receipts r,json_each(r.plan_json,'$.tenant_deletions') e JOIN nextcloud_onboarding_operations o ON o.operation_id=json_extract(e.value,'$.tenant.operation_id') AND o.instance_id=r.instance_id AND o.instance_id=json_extract(e.value,'$.tenant.instance_id') AND o.binding_id=json_extract(e.value,'$.tenant.binding_id') AND o.tenant_id=NEW.tenant_id WHERE r.plan_sha256=NEW.recovery_plan_sha256 AND json_extract(e.value,'$.tenant.tenant_id')=CAST(NEW.tenant_id AS TEXT) AND json_extract(e.value,'$.tenant.deletion_id')=NEW.deletion_id AND json_extract(e.value,'$.tenant.deletion_time_ms')=CAST(NEW.deletion_time_ms AS TEXT) AND json_extract(e.value,'$.tenant.closed_at')=CAST(NEW.closed_at_ms/1000 AS TEXT)))) BEGIN SELECT RAISE(ABORT,'nextcloud_target_closed'); END;
CREATE TRIGGER nextcloud_target_closure_insert_guard BEFORE INSERT ON nextcloud_onboarding_target_closures
WHEN NOT EXISTS(SELECT 1 FROM nextcloud_onboarding_operations o WHERE o.operation_id=NEW.operation_id AND o.tenant_id=NEW.tenant_id AND o.knowledge_base_id=NEW.knowledge_base_id AND o.instance_id=NEW.instance_id AND o.binding_id=NEW.binding_id AND o.revision>=NEW.operation_revision) OR NOT ((NEW.recovery_plan_sha256='' AND ((NEW.reason='tenant_deleted' AND EXISTS(SELECT 1 FROM tenants t WHERE t.id=NEW.tenant_id AND t.deleted_at IS NOT NULL)) OR (NEW.reason='knowledge_base_deleted' AND EXISTS(SELECT 1 FROM knowledge_bases k WHERE k.id=NEW.knowledge_base_id AND k.tenant_id=NEW.tenant_id AND k.deleted_at IS NOT NULL)))) OR (NEW.recovery_plan_sha256<>'' AND EXISTS(SELECT 1 FROM nextcloud_publication_recovery_receipts r,json_each(r.plan_json,'$.target_closures') e WHERE r.plan_sha256=NEW.recovery_plan_sha256 AND r.instance_id=NEW.instance_id AND json_extract(e.value,'$.target.closure_id')=NEW.closure_id AND json_extract(e.value,'$.target.operation_id')=NEW.operation_id AND json_extract(e.value,'$.target.tenant_id')=CAST(NEW.tenant_id AS TEXT) AND json_extract(e.value,'$.target.knowledge_base_id')=NEW.knowledge_base_id AND json_extract(e.value,'$.target.instance_id')=NEW.instance_id AND json_extract(e.value,'$.target.binding_id')=NEW.binding_id AND json_extract(e.value,'$.target.operation_revision')=CAST(NEW.operation_revision AS TEXT) AND json_extract(e.value,'$.target.reason')=NEW.reason AND json_extract(e.value,'$.target.deletion_time_ms')=CAST(NEW.deletion_time_ms AS TEXT)))) BEGIN SELECT RAISE(ABORT,'nextcloud_target_closed'); END;
CREATE TRIGGER nextcloud_target_operation_insert BEFORE INSERT ON nextcloud_onboarding_operations
WHEN (EXISTS(SELECT 1 FROM nextcloud_onboarding_tenant_deletions td WHERE td.tenant_id=NEW.tenant_id) OR EXISTS(SELECT 1 FROM nextcloud_onboarding_target_closures tc WHERE tc.tenant_id=NEW.tenant_id AND tc.knowledge_base_id=NEW.knowledge_base_id)) OR EXISTS(SELECT 1 FROM nextcloud_onboarding_tenant_deletions td WHERE td.tenant_id=NEW.tenant_id) OR NOT EXISTS(SELECT 1 FROM tenants t WHERE t.id=NEW.tenant_id AND t.deleted_at IS NULL) OR NOT EXISTS(SELECT 1 FROM knowledge_bases k WHERE k.id=NEW.knowledge_base_id AND k.tenant_id=NEW.tenant_id AND k.deleted_at IS NULL) BEGIN SELECT RAISE(ABORT,'nextcloud_target_closed'); END;
CREATE TRIGGER nextcloud_target_operation_update BEFORE UPDATE ON nextcloud_onboarding_operations
WHEN (EXISTS(SELECT 1 FROM nextcloud_onboarding_target_closures tc WHERE tc.operation_id=OLD.operation_id) OR EXISTS(SELECT 1 FROM nextcloud_onboarding_tenant_deletions td WHERE td.tenant_id=OLD.tenant_id)) AND (NEW.state<>'retired' OR NEW.permission_synced_at IS NOT NULL OR NEW.operation_id IS NOT OLD.operation_id OR NEW.credential_id IS NOT OLD.credential_id OR NEW.tenant_id IS NOT OLD.tenant_id OR NEW.knowledge_base_id IS NOT OLD.knowledge_base_id OR NEW.instance_id IS NOT OLD.instance_id OR NEW.binding_id IS NOT OLD.binding_id OR NEW.actor_directory_id IS NOT OLD.actor_directory_id OR NEW.actor_object_guid IS NOT OLD.actor_object_guid OR NEW.actor_user_id IS NOT OLD.actor_user_id OR NEW.request_sha256 IS NOT OLD.request_sha256) BEGIN SELECT RAISE(ABORT,'nextcloud_target_closed'); END;
CREATE TRIGGER nextcloud_target_operation_delete BEFORE DELETE ON nextcloud_onboarding_operations
WHEN (EXISTS(SELECT 1 FROM nextcloud_onboarding_tenant_deletions td WHERE td.tenant_id=OLD.tenant_id) OR EXISTS(SELECT 1 FROM nextcloud_onboarding_target_closures tc WHERE tc.tenant_id=OLD.tenant_id AND tc.knowledge_base_id=OLD.knowledge_base_id)) BEGIN SELECT RAISE(ABORT,'nextcloud_target_closed'); END;
