WHEN (EXISTS(SELECT 1 FROM nextcloud_onboarding_tenant_deletions td WHERE td.tenant_id=NEW.tenant_id) OR EXISTS(SELECT 1 FROM nextcloud_onboarding_target_closures tc WHERE tc.tenant_id=NEW.tenant_id AND tc.knowledge_base_id=NEW.knowledge_base_id)) BEGIN SELECT RAISE(ABORT,'nextcloud_target_closed'); END;
CREATE TRIGGER nextcloud_target_nextcloud_source_pairings_update BEFORE UPDATE ON nextcloud_source_pairings
WHEN ((EXISTS(SELECT 1 FROM nextcloud_onboarding_tenant_deletions td WHERE td.tenant_id=OLD.tenant_id) OR EXISTS(SELECT 1 FROM nextcloud_onboarding_target_closures tc WHERE tc.tenant_id=OLD.tenant_id AND tc.knowledge_base_id=OLD.knowledge_base_id)) OR (EXISTS(SELECT 1 FROM nextcloud_onboarding_tenant_deletions td WHERE td.tenant_id=NEW.tenant_id) OR EXISTS(SELECT 1 FROM nextcloud_onboarding_target_closures tc WHERE tc.tenant_id=NEW.tenant_id AND tc.knowledge_base_id=NEW.knowledge_base_id))) AND NEW.state NOT IN ('retired','decommissioned','withdrawn') BEGIN SELECT RAISE(ABORT,'nextcloud_target_closed'); END;
