WHEN ((EXISTS(SELECT 1 FROM nextcloud_onboarding_tenant_deletions td WHERE td.tenant_id=OLD.tenant_id) OR EXISTS(SELECT 1 FROM nextcloud_onboarding_target_closures tc WHERE tc.tenant_id=OLD.tenant_id AND tc.knowledge_base_id=OLD.knowledge_base_id)) OR (EXISTS(SELECT 1 FROM nextcloud_onboarding_tenant_deletions td WHERE td.tenant_id=NEW.tenant_id) OR EXISTS(SELECT 1 FROM nextcloud_onboarding_target_closures tc WHERE tc.tenant_id=NEW.tenant_id AND tc.knowledge_base_id=NEW.knowledge_base_id))) AND NEW.status<>'revoked' BEGIN SELECT RAISE(ABORT,'nextcloud_target_closed'); END;
