CREATE TRIGGER nextcloud_target_datasource_update BEFORE UPDATE ON data_sources
WHEN ((EXISTS(SELECT 1 FROM nextcloud_onboarding_tenant_deletions td WHERE td.tenant_id=OLD.tenant_id) OR EXISTS(SELECT 1 FROM nextcloud_onboarding_target_closures tc WHERE tc.tenant_id=OLD.tenant_id AND tc.knowledge_base_id=OLD.knowledge_base_id)) OR (EXISTS(SELECT 1 FROM nextcloud_onboarding_tenant_deletions td WHERE td.tenant_id=NEW.tenant_id) OR EXISTS(SELECT 1 FROM nextcloud_onboarding_target_closures tc WHERE tc.tenant_id=NEW.tenant_id AND tc.knowledge_base_id=NEW.knowledge_base_id))) AND (NEW.status<>'paused' OR NEW.sync_enabled IS NOT 0 OR NEW.id IS NOT OLD.id OR NEW.tenant_id IS NOT OLD.tenant_id OR NEW.knowledge_base_id IS NOT OLD.knowledge_base_id OR NEW.type IS NOT OLD.type OR NEW.config IS NOT OLD.config OR (OLD.deleted_at IS NOT NULL AND NEW.deleted_at IS NULL)) BEGIN SELECT RAISE(ABORT,'nextcloud_target_closed'); END;
