CREATE TRIGGER nextcloud_target_knowledges_update BEFORE UPDATE ON knowledges
WHEN ((EXISTS(SELECT 1 FROM nextcloud_onboarding_tenant_deletions td WHERE td.tenant_id=OLD.tenant_id) OR EXISTS(SELECT 1 FROM nextcloud_onboarding_target_closures tc WHERE tc.tenant_id=OLD.tenant_id AND tc.knowledge_base_id=OLD.knowledge_base_id)) OR (EXISTS(SELECT 1 FROM nextcloud_onboarding_tenant_deletions td WHERE td.tenant_id=NEW.tenant_id) OR EXISTS(SELECT 1 FROM nextcloud_onboarding_target_closures tc WHERE tc.tenant_id=NEW.tenant_id AND tc.knowledge_base_id=NEW.knowledge_base_id))) AND (NEW.id IS NOT OLD.id OR NEW.tenant_id IS NOT OLD.tenant_id OR NEW.knowledge_base_id IS NOT OLD.knowledge_base_id OR NEW.type IS NOT OLD.type OR NEW.title IS NOT OLD.title OR NEW.description IS NOT OLD.description OR NEW.source IS NOT OLD.source OR NEW.channel IS NOT OLD.channel OR NEW.pending_subtasks_count IS NOT OLD.pending_subtasks_count OR NEW.summary_status IS NOT OLD.summary_status OR NEW.profile IS NOT OLD.profile OR NEW.embedding_model_id IS NOT OLD.embedding_model_id OR NEW.file_name IS NOT OLD.file_name OR NEW.folder_path IS NOT OLD.folder_path OR NEW.file_type IS NOT OLD.file_type OR NEW.file_size IS NOT OLD.file_size OR NEW.file_hash IS NOT OLD.file_hash OR NEW.file_path IS NOT OLD.file_path OR NEW.storage_size IS NOT OLD.storage_size OR NEW.custom_metadata IS NOT OLD.custom_metadata OR NEW.last_faq_import_result IS NOT OLD.last_faq_import_result OR NEW.created_at IS NOT OLD.created_at OR NEW.processed_at IS NOT OLD.processed_at OR NEW.error_message IS NOT OLD.error_message OR NEW.enable_status<>'disabled' OR (NEW.parse_status IS NOT OLD.parse_status AND NEW.parse_status NOT IN ('deleting','cancelled')) OR json_remove(COALESCE(NEW.metadata,'{}'),'$.nextcloud_etag') IS NOT json_remove(COALESCE(OLD.metadata,'{}'),'$.nextcloud_etag') OR COALESCE(json_extract(NEW.metadata,'$.nextcloud_etag'),'')<>'' OR (OLD.deleted_at IS NOT NULL AND NEW.deleted_at IS NULL)) BEGIN SELECT RAISE(ABORT,'nextcloud_target_closed'); END;
