CREATE TRIGGER nextcloud_target_tenant_insert BEFORE INSERT ON tenants
WHEN EXISTS(SELECT 1 FROM nextcloud_onboarding_tenant_deletions td WHERE td.tenant_id=NEW.id) BEGIN SELECT RAISE(ABORT,'nextcloud_target_closed'); END;
CREATE TRIGGER nextcloud_target_tenant_undelete BEFORE UPDATE OF deleted_at ON tenants
WHEN OLD.deleted_at IS NOT NULL AND NEW.deleted_at IS NULL AND EXISTS(SELECT 1 FROM nextcloud_onboarding_tenant_deletions td WHERE td.tenant_id=OLD.id) BEGIN SELECT RAISE(ABORT,'nextcloud_target_closed'); END;
